/* Composite levels (drakensang_mod_composites[_<exe>].txt, generated by tools/gen_composites.py):
 * travel to a base level, hide some of its static objects while it loads, then place the models
 * and SpeedTrees of the composite (e.g. the other three Ferdok districts and a forest outside the
 * city walls). Graphics only: collision, NPCs and scripts stay those of the base level. */
#include "game.h"

#define MAX_COMPOSITES 8
#define MAX_HIDE 32

typedef struct Composite {
    char id[64], title[128], base[64], entry[128];
    char hide[MAX_HIDE][48];
    int  nhide;
    char *items;            /* first item line in g_buf; lines are NUL-separated */
    int  nitems, nmodels, ntrees;
} Composite;

static Composite g_comp[MAX_COMPOSITES];
static int g_ncomp, g_loaded;
static char *g_buf;

enum { C_IDLE, C_LOADING, C_ACTIVE };
static int g_state, g_cur, g_wait, g_sawChange, g_sawPending, g_serial;
static double g_quietSince;
static BYTE *g_fromLevel, *g_fromCam, *g_activeLevel;
static double g_since;

static void load(void)
{
    WCHAR path[MAX_PATH];
    HANDLE f;
    DWORD size, n = 0;
    char *p, *end;
    Composite *c = NULL;
    g_loaded = 1;
    g_ncomp = 0;
    game_data_file(path, L"drakensang_mod_composites");
    f = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (f == INVALID_HANDLE_VALUE) return;
    size = GetFileSize(f, NULL);
    if (g_buf) HeapFree(GetProcessHeap(), 0, g_buf);
    g_buf = (char *)HeapAlloc(GetProcessHeap(), 0, size + 2);
    if (g_buf) ReadFile(f, g_buf, size, &n, NULL);
    CloseHandle(f);
    if (!g_buf) return;
    g_buf[n] = 0;
    end = g_buf + n;
    for (p = g_buf; p < end;) {
        char *line = p, *nl = strchr(p, '\n');
        if (nl) *nl = 0;
        p = nl ? nl + 1 : end;
        if (nl && nl > line && nl[-1] == '\r') nl[-1] = 0;
        if (!strcmp(line, "[composite]")) {
            c = g_ncomp < MAX_COMPOSITES ? &g_comp[g_ncomp++] : NULL;
            if (c) memset(c, 0, sizeof *c);
        } else if (!strcmp(line, "[end]")) {
            c = NULL;
        } else if (c && (line[0] == 'm' || line[0] == 't') && line[1] == '|') {
            if (!c->items) c->items = line;
            c->nitems++;
            if (line[0] == 'm') c->nmodels++;
            else c->ntrees++;
        } else if (c && !strncmp(line, "id=", 3)) {
            strncpy(c->id, line + 3, sizeof c->id - 1);
        } else if (c && !strncmp(line, "title=", 6)) {
            strncpy(c->title, line + 6, sizeof c->title - 1);
        } else if (c && !strncmp(line, "base=", 5)) {
            strncpy(c->base, line + 5, sizeof c->base - 1);
        } else if (c && !strncmp(line, "entry=", 6)) {
            strncpy(c->entry, line + 6, sizeof c->entry - 1);
        } else if (c && !strncmp(line, "hide=", 5) && c->nhide < MAX_HIDE) {
            strncpy(c->hide[c->nhide++], line + 5, 47);
        }
    }
    mlog("composites: %d loaded from %ls", g_ncomp, path);
}

int composite_count(void)
{
    if (!g_loaded) load();
    return g_ncomp;
}

const char *composite_title(int i)
{
    return i >= 0 && i < g_ncomp ? g_comp[i].title : "";
}

/* Travel to the base level; the objects are placed once it has loaded. */
int composite_start(int i, char *err, int errsz)
{
    Composite *c;
    if (i < 0 || i >= composite_count()) return snprintf(err, errsz, "no such composite level"), 0;
    c = &g_comp[i];
    if (!level_travel(c->base, c->entry, err, errsz)) return 0;
    spawn_set_hide((const char(*)[48])c->hide, c->nhide);
    g_cur = i;
    g_state = C_LOADING;
    g_fromLevel = spawn_current_level();
    g_fromCam = cam_main();
    g_sawChange = g_wait = g_sawPending = 0;
    g_serial = level_load_serial();
    g_quietSince = 0;
    g_since = now_seconds();
    mlog("composite %s: travelling to %s @ %s (%d models, %d trees)", c->id, c->base, c->entry, c->nmodels, c->ntrees);
    return 1;
}

static void place_all(const Composite *c)
{
    const char *line = c->items;
    int i, nm = 0, nt = 0;
    for (i = 0; i < c->nitems; i++, line += strlen(line) + 1) {
        char res[96] = {0};
        const char *bar = strchr(line + 2, '|');
        float m[16], lod[2] = {10.0f, 60.0f}, br[4] = {1, 1, 1, 1};
        char *q;
        int k;
        if (!bar || bar - (line + 2) >= (int)sizeof res) continue;
        memcpy(res, line + 2, bar - (line + 2));
        q = (char *)bar + 1;
        for (k = 0; k < 16; k++) m[k] = (float)strtod(q, &q);
        if (line[0] == 'm') {
            nm += spawn_model(res, m) != 0;
            continue;
        }
        if (*q == '|') {
            q++;
            lod[0] = (float)strtod(q, &q);
            lod[1] = (float)strtod(q, &q);
        }
        if (*q == '|') {
            q++;
            for (k = 0; k < 4; k++) br[k] = (float)strtod(q, &q);
        }
        nt += spawn_tree(res, m, lod[0], lod[1], br) != 0;
    }
    mlog("composite %s: queued %d models, %d trees (base objects hidden: %d)", c->id, nm, nt, spawn_hidden_count());
    toast("%s: placing %d buildings and objects, %d trees", c->title, nm, nt);
}

void composite_frame(void)
{
    if (g_state == C_LOADING) {
        BYTE *lvl = spawn_current_level(), *cam = cam_main();
        int busy = level_travel_queued() || level_change_pending() || level_loading();
        if (busy) {
            g_sawPending = 1;
            g_wait = 0;
            g_quietSince = 0;
            return;
        }
        if (g_quietSince == 0) g_quietSince = now_seconds();
        if (!lvl || !cam || lvl != g_fromLevel || cam != g_fromCam) g_sawChange = 1;
        if (now_seconds() - g_since > 300.0) {
            spawn_set_hide(NULL, 0);
            g_state = C_IDLE;
            toast("Composite level: the level did not load");
            return;
        }
        if (!g_sawPending || !lvl || !cam) return;   /* the travel has not started / finished yet */
        /* wait for the level load; a travel inside the current level does not reload it */
        if (level_load_serial() == g_serial && now_seconds() - g_quietSince < 4.0) return;
        if (++g_wait < 60) return;   /* let the level settle */
        /* the base level may not have been reloaded (travel within it): detach matching objects now */
        spawn_hide_attached((const char(*)[48])g_comp[g_cur].hide, g_comp[g_cur].nhide);
        g_activeLevel = lvl;
        g_state = C_ACTIVE;
        place_all(&g_comp[g_cur]);
    } else if (g_state == C_ACTIVE && spawn_current_level() != g_activeLevel) {
        g_state = C_IDLE;
    }
}

int composite_command(const char *cmd, const char *arg, char *out, int outsz)
{
    if (!_stricmp(cmd, "composites")) {
        int i, len = snprintf(out, outsz, "%d composite levels (state %d):", composite_count(), g_state);
        for (i = 0; i < g_ncomp && len < outsz - 200; i++)
            len += snprintf(out + len, outsz - len, "\n%d %s: %s (base %s @ %s, %d models, %d trees, %d hidden)",
                            i + 1, g_comp[i].id, g_comp[i].title, g_comp[i].base, g_comp[i].entry, g_comp[i].nmodels,
                            g_comp[i].ntrees, g_comp[i].nhide);
        return 1;
    }
    if (!_stricmp(cmd, "composite")) {   /* composite <n> */
        char err[160];
        if (composite_start(atoi(arg) - 1, err, sizeof err)) snprintf(out, outsz, "loading %s", g_comp[g_cur].title);
        else snprintf(out, outsz, "FAILED: %s", err);
        return 1;
    }
    return 0;
}
